## 1. Add a small ONNX‑Runtime helper (shared/api.js)

```javascript
// app/src/shared/api.js
// ---------------------------------------------------------------
// Centralised ONNX Runtime Web loader with GPU‑accelerated providers.
// ---------------------------------------------------------------
import * as ort from 'onnxruntime-web';

let sessionCache = {};

export async function loadOnnxModel(relativePath) {
  // `relativePath` is relative to the public folder (e.g. "modelB_trajectory.onnx")
  // We request WebGPU first, then fall back to WASM.
  const options = {
    executionProviders: ['webgpu', 'wasm'],
  };
  const modelUrl = `${process.env.PUBLIC_URL}/${relativePath}`;
  // Re‑use cached session if already loaded.
  if (sessionCache[modelUrl]) return sessionCache[modelUrl];
  const session = await ort.InferenceSession.create(modelUrl, options);
  sessionCache[modelUrl] = session;
  return session;
}

/**
 * Runs a model and returns the raw output tensor(s).
 * `inputs` must be a plain object: {input: Float32Array([...])}
 */
export async function runModel(session, inputs) {
  const feeds = {};
  // ONNX‑Runtime expects a named Tensor; we use the first input name.
  const inputName = session.inputNames[0];
  feeds[inputName] = new ort.Tensor('float32', inputs[inputName], [1, inputs[inputName].length]);
  const results = await session.run(feeds);
  // Return the first output (most models have a single output)
  const outputName = session.outputNames[0];
  return results[outputName];
}
```

*Why this file?*  
- Guarantees **GPU‑accelerated inference** (`executionProviders: ['webgpu','wasm']`).  
- Caches the `InferenceSession` so the model is loaded only once per page load.  

